INSERT INTO public.playbook_worksheets (id, company_id, goal_key, title, objective_id, hoshin_item_id, inputs, notes, status) VALUES ('aa000000-0000-0000-0000-000000000001', '9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'otd', 'OTD recovery — AOG bracket line', '11000000-0000-0000-0000-000000000003', '30000000-0000-0000-0000-000000000011', '{"otd_current":78,"otd_target":95,"schedule_adherence":72,"lead_time_days":21,"actual_lead_time_days":29,"main_miss_reason":"material","wip_orders":140}'::jsonb, 'Built in the weekly ops review after three consecutive months below 80% OTD on the AOG bracket line.', 'active');
INSERT INTO public.playbook_items (company_id, worksheet_id, kind, rule_key, text, rationale, horizon, impact, effort, accepted, due_date, sort_order) VALUES
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'action', 'otd_stabilise_schedule', 'Freeze the schedule for the next 5 days and run a daily schedule-adherence review', 'OTD gap of 17 points with schedule adherence at 72% — stabilise the schedule before adding capacity.', 'week', 'high', 'med', true, '2026-09-04', 0),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'action', 'otd_supplier', 'Put the top 5 late suppliers on a weekly confirmed-delivery call and re-plan around their real dates', 'Material shortage is the biggest miss reason — supplier promise dates drive your OTD.', 'month', 'high', 'med', true, '2026-09-18', 1),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'action', 'otd_leadtime_gap', 'Requote lead time to reality on new orders while the recovery runs', 'Actual lead time (29 days) is more than 20% above the quoted 21 days — you are promising something the process does not do.', 'week', 'med', 'low', false, null, 2),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'action', 'otd_wip', 'Cap work in progress — release new work only when an order ships', 'Lead time is running over quote with open work on the floor; more WIP lengthens every queue.', 'month', 'med', 'med', false, null, 3),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_stabilise_schedule', 'The schedule is achievable if it is left alone', 'Run one week frozen and measure adherence against the same load', null, null, 'med', false, null, 100),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_stabilise_schedule', 'Late changes come from inside the plant, not from customers', 'Log every schedule change for a week with its origin', null, null, 'low', false, null, 101),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_supplier', 'Supplier lateness is concentrated in a handful of suppliers', 'Rank supplier OTD for the last quarter by number of late lines', null, null, 'low', false, null, 102),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_supplier', 'Your own purchase orders are placed with enough lead time', 'Compare PO placement date to supplier quoted lead time on 20 late lines', null, null, 'low', false, null, 103),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_leadtime_gap', 'Customers will accept a longer but reliable date', 'Test the longer date on the next 5 quotes and record the win rate', null, null, 'low', false, null, 104),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'assumption', 'otd_wip', 'The floor has more work released than it can flow', 'Track WIP and shipments daily for two weeks and compare the ratio', null, null, 'low', false, null, 105),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'watch', null, 'OTD to original request date', null, null, null, null, false, null, 200),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'watch', null, 'Schedule adherence', null, null, null, null, false, null, 201),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000001', 'watch', null, 'Average days late on the misses', null, null, null, null, false, null, 202);
INSERT INTO public.playbook_worksheets (id, company_id, goal_key, title, objective_id, hoshin_item_id, inputs, notes, status) VALUES ('aa000000-0000-0000-0000-000000000002', '9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'copq', 'Scrap and rework reduction — 5-axis machining cell', '11000000-0000-0000-0000-000000000002', '30000000-0000-0000-0000-000000000012', '{"scrap_rate":4.8,"scrap_target":3.5,"rework_hours":320,"copq_cost":148000,"escapes":3,"detection_point":"final","top_driver_share":62}'::jsonb, 'Titanium scrap is the single largest material loss in the plant; this worksheet frames the first 90 days.', 'active');
INSERT INTO public.playbook_items (company_id, worksheet_id, kind, rule_key, text, rationale, horizon, impact, effort, accepted, due_date, sort_order) VALUES
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'action', 'copq_customer_detection', 'Contain first: add a temporary 100% check before despatch on the affected parts, then work back to the source', 'Defects are reaching the customer — protect the customer while the root cause is found.', 'week', 'high', 'low', false, null, 0),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'action', 'copq_final_inspection', 'Move detection upstream — add an in-process check at the operation that creates the defect', 'Defects are being caught at final inspection, so you are paying full processing cost on parts you then scrap.', 'month', 'high', 'med', false, null, 1),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'action', 'copq_top_driver', 'Open a structured problem-solving case (8D or A3) on the top driver and assign a single owner', 'The top driver carries 62% of the cost — one case can move most of the number.', 'month', 'high', 'med', false, null, 2),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'action', 'copq_rework_heavy', 'Treat rework hours as lost capacity — put them on the daily board next to output', '320 rework hours a month is capacity you already paid for.', 'week', 'med', 'low', false, null, 3),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'assumption', 'copq_customer_detection', 'The escapes share a common part family or process', 'Map the last 10 escapes to part, operation and shift', null, null, 'low', false, null, 100),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'assumption', 'copq_customer_detection', 'The check can actually detect the defect', 'Seed 5 known-bad samples through the check and count how many are caught', null, null, 'low', false, null, 101),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'assumption', 'copq_final_inspection', 'The defect is created at one identifiable operation', 'Run a check sheet at the three candidate operations for a week', null, null, 'med', false, null, 102),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'assumption', 'copq_top_driver', 'The top driver is a process problem, not a design or specification problem', 'Check whether the same defect appears across all machines and shifts', null, null, 'med', false, null, 103),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'assumption', 'copq_rework_heavy', 'Rework hours are booked separately from production hours', 'Check whether operators have a distinct rework booking code', null, null, 'low', false, null, 104),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'watch', null, 'Scrap rate', null, null, null, null, false, null, 200),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'watch', null, 'Rework hours', null, null, null, null, false, null, 201),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'watch', null, 'Customer escapes', null, null, null, null, false, null, 202),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000002', 'watch', null, 'Cost of poor quality per month', null, null, null, null, false, null, 203);
INSERT INTO public.playbook_worksheets (id, company_id, goal_key, title, objective_id, hoshin_item_id, inputs, notes, status) VALUES ('aa000000-0000-0000-0000-000000000003', '9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'cash', 'Free up cash — inventory and receivables', null, '30000000-0000-0000-0000-000000000014', '{"inventory_value":6200000,"inventory_turns":3.1,"dso_days":62,"dpo_days":41,"wip_value":1450000,"overdue_receivables":480000,"cash_runway_weeks":11}'::jsonb, 'Working-capital review ahead of the CMM inspection cell investment.', 'active');
INSERT INTO public.playbook_items (company_id, worksheet_id, kind, rule_key, text, rationale, horizon, impact, effort, accepted, due_date, sort_order) VALUES
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'action', 'cash_overdue', 'Call the top 10 overdue accounts personally this week and agree a dated payment plan for each', 'There is money already earned and unpaid — this is the cheapest cash in the business.', 'week', 'high', 'low', false, null, 0),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'action', 'cash_dso', 'Tighten the invoice cycle — invoice on despatch, not at month end, and chase at day 3 past due', 'Debtor days at 62 means you are funding customers for over six weeks.', 'month', 'high', 'med', false, null, 1),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'action', 'cash_turns', 'Segment inventory into fast, slow and dead, and stop reordering anything in the dead bucket', '3.1 turns a year means the average item sits over two months.', 'month', 'high', 'med', false, null, 2),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'action', 'cash_terms', 'Renegotiate payment terms so you are not paying suppliers faster than customers pay you', 'You collect in 62 days and pay in 41 — the gap is funded from your own cash.', 'quarter', 'med', 'med', false, null, 3),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'assumption', 'cash_overdue', 'The overdue invoices are undisputed', 'Check each of the top 10 for open queries or missing paperwork', null, null, 'low', false, null, 100),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'assumption', 'cash_dso', 'The delay is in your invoicing, not in the customer''s terms', 'Measure days from despatch to invoice sent on 20 recent orders', null, null, 'low', false, null, 101),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'assumption', 'cash_turns', 'Slow-moving stock is not there to protect a real service commitment', 'Check the slow bucket against contracted spares or safety-stock agreements', null, null, 'med', false, null, 102),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'assumption', 'cash_terms', 'Suppliers will extend terms without raising price', 'Test the ask with two suppliers and compare the quoted price impact', null, null, 'low', false, null, 103),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'watch', null, '13-week cash forecast', null, null, null, null, false, null, 200),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'watch', null, 'Debtor days', null, null, null, null, false, null, 201),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'watch', null, 'Inventory turns', null, null, null, null, false, null, 202),
('9d12cf46-98e4-40ca-aed4-bcc95257d8b5', 'aa000000-0000-0000-0000-000000000003', 'watch', null, 'Overdue receivables', null, null, null, null, false, null, 203);
